from __future__ import annotations

from typing import Any


class EmailGateway:
    def __init__(self) -> None:
        self._sent: list[dict[str, Any]] = []

    def send(self, *, to_email: str, subject: str, body: str, event_type: str) -> dict[str, Any]:
        payload = {
            "to_email": to_email.strip().lower(),
            "subject": subject.strip(),
            "body": body.strip(),
            "event_type": event_type.strip(),
            "ok": True,
        }
        self._sent.append(payload)
        return dict(payload)

    def sent_count(self) -> int:
        return len(self._sent)

    def list_sent(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._sent]

    def by_event_type(self, event_type: str) -> list[dict[str, Any]]:
        key = event_type.strip()
        return [dict(item) for item in self._sent if str(item.get("event_type", "")) == key]

    def clear(self) -> None:
        self._sent.clear()

    def last(self) -> dict[str, Any] | None:
        if not self._sent:
            return None
        return dict(self._sent[-1])

    def has_recipient(self, email: str) -> bool:
        target = email.strip().lower()
        return any(str(item.get("to_email", "")).lower() == target for item in self._sent)

    def count_by_type(self, event_type: str) -> int:
        key = event_type.strip()
        return len([item for item in self._sent if str(item.get("event_type", "")) == key])

    def recipients(self) -> list[str]:
        return sorted({str(item.get("to_email", "")).strip().lower() for item in self._sent if item.get("to_email")})

    def summary(self) -> dict[str, int]:
        out: dict[str, int] = {}
        for item in self._sent:
            key = str(item.get("event_type", "unknown"))
            out[key] = out.get(key, 0) + 1
        return out

    def remove_last(self) -> dict[str, Any] | None:
        if not self._sent:
            return None
        return self._sent.pop()

    def export_lines(self) -> list[str]:
        return [
            f"{item['event_type']}->{item['to_email']}:{item['subject']}"
            for item in self._sent
        ]

    def first(self) -> dict[str, Any] | None:
        if not self._sent:
            return None
        return dict(self._sent[0])

    def remove_by_type(self, event_type: str) -> int:
        key = event_type.strip()
        before = len(self._sent)
        self._sent = [item for item in self._sent if str(item.get("event_type", "")) != key]
        return before - len(self._sent)

    def has_subject(self, subject: str) -> bool:
        target = subject.strip()
        if not target:
            return False
        return any(str(item.get("subject", "")).strip() == target for item in self._sent)

