from typing import Any


class EventStore:
    def __init__(self) -> None:
        self._events: list[dict[str, Any]] = []
        self._users: dict[str, dict[str, Any]] = {}

    def seed_users(self, users: list[dict[str, Any]]) -> None:
        self._users.clear()
        for user in users:
            user_id = str(user.get("user_id", "")).strip()
            if not user_id:
                raise ValueError("user_id required")
            self._users[user_id] = {
                "user_id": user_id,
                "email": str(user.get("email", "")).strip().lower(),
                "name": str(user.get("name", "")).strip(),
                "notifications_enabled": bool(user.get("notifications_enabled", True)),
            }
        self._events.clear()

    def get_user(self, user_id: str) -> dict[str, Any] | None:
        key = user_id.strip()
        if not key:
            return None
        user = self._users.get(key)
        if user is None:
            return None
        return dict(user)

    def append_event(self, event: dict[str, Any]) -> None:
        self._events.append(dict(event))

    def list_events(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._events]

    def count_events(self) -> int:
        return len(self._events)

    def users_count(self) -> int:
        return len(self._users)

    def clear_events(self) -> None:
        self._events.clear()

    def events_by_type(self, event_type: str) -> list[dict[str, Any]]:
        key = event_type.strip()
        return [dict(item) for item in self._events if str(item.get("event_type", "")) == key]

    def snapshot(self) -> dict[str, Any]:
        return {
            "users": {key: dict(value) for key, value in self._users.items()},
            "events": [dict(item) for item in self._events],
        }

    def user_ids(self) -> list[str]:
        return sorted(self._users.keys())

    def has_user(self, user_id: str) -> bool:
        return user_id.strip() in self._users

    def update_user(self, user_id: str, updates: dict[str, Any]) -> bool:
        key = user_id.strip()
        if not key or key not in self._users:
            return False
        current = dict(self._users[key])
        current.update(dict(updates))
        self._users[key] = current
        return True

    def remove_user(self, user_id: str) -> bool:
        key = user_id.strip()
        if not key:
            return False
        if key in self._users:
            del self._users[key]
            return True
        return False

