from __future__ import annotations

from typing import Any

from email_gateway import EmailGateway
from event_store import EventStore


NOTIFIABLE_EVENTS = {"invoice_paid", "invoice_failed", "trial_expiring"}


def _build_email(event_type: str, user: dict[str, Any], payload: dict[str, Any]) -> dict[str, str]:
    name = str(user.get("name", "")).strip() or "there"
    amount = str(payload.get("amount", ""))
    if event_type == "invoice_paid":
        return {
            "subject": "Payment received",
            "body": f"Hi {name}, we received your payment of {amount}.",
        }
    if event_type == "invoice_failed":
        return {
            "subject": "Payment failed",
            "body": f"Hi {name}, your recent payment attempt failed.",
        }
    return {
        "subject": "Trial expiring soon",
        "body": f"Hi {name}, your trial is expiring soon.",
    }


def handle_event(payload: dict[str, Any], store: EventStore, gateway: EmailGateway) -> dict[str, Any]:
    event_type = str(payload.get("event_type", "")).strip()
    user_id = str(payload.get("user_id", "")).strip()
    metadata = dict(payload.get("metadata", {}) or {})

    if not event_type:
        return {"ok": False, "reason": "invalid_event_type"}
    if not user_id:
        return {"ok": False, "reason": "invalid_user_id"}

    user = store.get_user(user_id)
    if user is None:
        return {"ok": False, "reason": "user_not_found"}

    event_record = {"event_type": event_type, "user_id": user_id, "metadata": metadata}
    store.append_event(event_record)

    sent_email = None
    if event_type in NOTIFIABLE_EVENTS:
        if user.get("notifications_enabled", True):
            message = _build_email(event_type, user, metadata)
            # Bug: hook is not wired for invoice_failed even though it is notifiable.
            if event_type != "invoice_failed":
                sent_email = gateway.send(
                    to_email=str(user.get("email", "")),
                    subject=message["subject"],
                    body=message["body"],
                    event_type=event_type,
                )

    return {"ok": True, "reason": "processed", "event": event_record, "email": sent_email}


def handle_batch(payloads: list[dict[str, Any]], store: EventStore, gateway: EmailGateway) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        result = handle_event(payload, store, gateway)
        results.append(result)
        if result.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "results": results}


def summarize_results(results: list[dict[str, Any]]) -> dict[str, int]:
    success = 0
    failed = 0
    with_email = 0
    for result in results:
        if bool(result.get("ok", False)):
            success += 1
        else:
            failed += 1
        if result.get("email") is not None:
            with_email += 1
    return {"success": success, "failed": failed, "with_email": with_email}


def should_notify(event_type: str, notifications_enabled: bool) -> bool:
    if event_type not in NOTIFIABLE_EVENTS:
        return False
    return bool(notifications_enabled)


def make_diagnostics(store: EventStore, gateway: EmailGateway) -> dict[str, Any]:
    return {
        "event_count": store.count_events(),
        "audit_summary": {k: len(v) for k, v in {"all": store.list_events()}.items()},
        "email_count": gateway.sent_count(),
        "email_summary": gateway.summary(),
    }

